package dev.pixel.calculator.agent;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;

public class MainActivity extends Activity {
 static MainActivity instance; private CalculatorSession session; private Calculator calc;private TextView display,expression;private Button clear;private LinearLayout root,keypad;private final Map<String,Button> ops=new HashMap<>();private JSONArray history=new JSONArray();private float touchX;private int keyHeight=72;
 private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 @Override public void onCreate(Bundle state){PixelAppearance.attach(this);super.onCreate(state);instance=this;PixelAppearance.bars(this);PixelStyle.install(this,false);restore();getWindow().setStatusBarColor(PixelAppearance.color(0xffb9dff3));getWindow().setNavigationBarColor(PixelAppearance.color(0xffb9dff3));build();render();}
 private void build(){
  root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(PixelAppearance.color(0xffb9dff3));root.setPadding(dp(14),dp(8),dp(14),dp(12));root.setOnApplyWindowInsetsListener((v,in)->{Insets b=in.getInsets(WindowInsets.Type.systemBars());v.setPadding(dp(14)+b.left,dp(8)+b.top,dp(14)+b.right,dp(12)+b.bottom);return in;});setContentView(root);
  LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);TextView name=new TextView(this);name.setText("Calculator");name.setTextColor(PixelAppearance.color(0xff576f90));name.setTextSize(17);bar.addView(name,new LinearLayout.LayoutParams(0,dp(44),1));Button hist=new Button(this);hist.setText("◷");hist.setTextSize(26);hist.setAllCaps(false);hist.setTextColor(PixelAppearance.color(0xff3f567a));hist.setBackgroundColor(Color.TRANSPARENT);hist.setContentDescription("Calculation history");hist.setOnClickListener(v->showHistory());bar.addView(hist);root.addView(bar);
  boolean landscape=getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE;
  LinearLayout content=new LinearLayout(this);content.setOrientation(landscape?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));
  LinearLayout output=new LinearLayout(this);output.setOrientation(LinearLayout.VERTICAL);output.setGravity(Gravity.BOTTOM|Gravity.END);content.addView(output,landscape?new LinearLayout.LayoutParams(0,-1,.85f):new LinearLayout.LayoutParams(-1,0,1));
  expression=new TextView(this);expression.setTextColor(PixelAppearance.color(0xff576f90));expression.setTextSize(20);expression.setGravity(Gravity.END);expression.setSingleLine(true);expression.setEllipsize(android.text.TextUtils.TruncateAt.START);output.addView(expression,new LinearLayout.LayoutParams(-1,dp(30)));
  display=new TextView(this);display.setTextColor(PixelAppearance.color(0xff29385d));display.setTypeface(Typeface.create("sans-serif-light",Typeface.NORMAL));display.setGravity(Gravity.END|Gravity.BOTTOM);display.setSingleLine(true);display.setHorizontallyScrolling(false);display.setTextSize(78);display.setAutoSizeTextTypeUniformWithConfiguration(22,78,2,android.util.TypedValue.COMPLEX_UNIT_SP);display.setPadding(dp(2),0,dp(8),0);display.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);output.addView(display,new LinearLayout.LayoutParams(-1,0,1));
  display.setOnLongClickListener(v->{copy();return true;});display.setOnTouchListener((v,event)->{if(event.getAction()==MotionEvent.ACTION_DOWN)touchX=event.getX();if(event.getAction()==MotionEvent.ACTION_UP&&Math.abs(event.getX()-touchX)>dp(45)){key("back");return true;}return false;});
  LinearLayout edit=new LinearLayout(this);edit.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);edit.setPadding(0,0,dp(5),dp(8));
  ImageButton back=new ImageButton(this);back.setImageDrawable(getDrawable(getResources().getIdentifier("backspace","drawable",getPackageName())));back.setScaleType(ImageView.ScaleType.FIT_CENTER);back.setColorFilter(PixelAppearance.color(0xff29385d));back.setPadding(dp(16),dp(12),dp(16),dp(12));back.setMinimumWidth(0);back.setMinimumHeight(0);back.setBackground(background(PixelAppearance.color(0xffd5e7f2)));back.setContentDescription("Delete last digit");back.setOnClickListener(v->{back.performHapticFeedback(HapticFeedbackConstants.KEYBOARD_TAP);key("back");});edit.addView(back,new LinearLayout.LayoutParams(dp(64),dp(52)));output.addView(edit,new LinearLayout.LayoutParams(-1,dp(60)));
  keypad=new LinearLayout(this);keypad.setOrientation(LinearLayout.VERTICAL);content.addView(keypad,landscape?new LinearLayout.LayoutParams(0,-1,1.15f):new LinearLayout.LayoutParams(-1,dp(420)));
  String[][] rows={{"AC","±","%","÷"},{"7","8","9","×"},{"4","5","6","−"},{"1","2","3","+"},{"0",".","="}};
  for(String[] row:rows){LinearLayout line=new LinearLayout(this);keypad.addView(line,new LinearLayout.LayoutParams(-1,0,1));for(String label:row){Button b=new Button(this);b.setAllCaps(false);b.setText(label);b.setTextSize(32);b.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));b.setPadding(0,0,0,0);b.setMinHeight(0);b.setMinimumHeight(0);b.setMinWidth(0);b.setMinimumWidth(0);boolean orange="÷×−+=".contains(label);boolean gray=label.equals("AC")||label.equals("±")||label.equals("%");b.setTextColor(PixelAppearance.color(0xff29385d));b.setBackground(background(orange?0xffffd66b:gray?PixelAppearance.color(0xffd5e7f2):PixelAppearance.color(0xfffff7e5)));if(label.equals("AC"))clear=b;if(orange)ops.put(label,b);
   b.setContentDescription(description(label));b.setOnClickListener(v->{b.performHapticFeedback(HapticFeedbackConstants.KEYBOARD_TAP);key(label.equals("AC")?clear.getText().toString():label);});if(label.equals("AC"))b.setOnLongClickListener(v->{key("AC");return true;});
   LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,label.equals("0")?2:1);p.setMargins(dp(5),dp(5),dp(5),dp(5));line.addView(b,p);}}
  content.addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob)->{int available=content.getHeight();int width=content.getWidth();int desired=landscape?available:Math.min(5*(width/4),Math.max(dp(200),available-dp(216)));if(!landscape&&keypad.getLayoutParams().height!=desired){keypad.getLayoutParams().height=desired;keypad.requestLayout();}int font=desired<dp(300)?23:32;for(int i=0;i<keypad.getChildCount();i++){LinearLayout row=(LinearLayout)keypad.getChildAt(i);for(int j=0;j<row.getChildCount();j++)((Button)row.getChildAt(j)).setTextSize(font);}});
 }
 private android.graphics.drawable.Drawable background(int color){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(100));return new RippleDrawable(android.content.res.ColorStateList.valueOf(0x55ffffff),g,null);}
 private String description(String s){switch(s){case "AC":return "Clear; hold to clear all";case "±":return "Change sign";case "%":return "Percent";case "÷":return "Divide";case "×":return "Multiply";case "−":return "Subtract";case "+":return "Add";case "=":return "Equals";case ".":return "Decimal point";default:return s;}}
 private void key(String k){session.press(k);history=session.history;render();}
 private void render(){display.setText(calc.entry);display.setContentDescription("Result "+calc.entry);expression.setText(calc.expression());clear.setText(calc.entry.equals("0")||calc.result||calc.error?"AC":"C");for(Map.Entry<String,Button> e:ops.entrySet()){boolean active=e.getKey().equals(calc.activeOperator());e.getValue().setBackground(background(active?PixelAppearance.color(0xff29385d):0xffffd66b));e.getValue().setTextColor(active?0xffffd66b:PixelAppearance.color(0xff29385d));}}
 private void copy(){((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Calculator result",calc.entry));Toast.makeText(this,"Result copied",Toast.LENGTH_SHORT).show();}
 private void showHistory(){if(history.length()==0){new AlertDialog.Builder(this).setTitle("History").setMessage("Your calculations will appear here.").setPositiveButton("Done",null).show();return;}String[] items=new String[history.length()];for(int i=0;i<items.length;i++){JSONObject item=history.optJSONObject(i);items[i]=item.optString("expression")+" = "+item.optString("answer");}new AlertDialog.Builder(this).setTitle("History · tap to reuse").setItems(items,(d,n)->{calc.recall(history.optJSONObject(n).optString("answer","0"));render();save();}).setPositiveButton("Done",null).setNeutralButton("Clear history",(d,n)->{history=new JSONArray();save();}).show();}
 private void save(){session.history=history;session.save();}
 private void restore(){session=CalculatorSession.get(this);calc=session.calc;history=session.history;}
 void refreshFromSession(){restore();render();}
 @Override protected void onResume(){super.onResume();if(session!=null)refreshFromSession();}
 @Override protected void onDestroy(){if(instance==this)instance=null;super.onDestroy();}
 @Override public boolean onKeyDown(int code,KeyEvent event){if(code==KeyEvent.KEYCODE_DEL){key("back");return true;}if(code==KeyEvent.KEYCODE_ENTER||code==KeyEvent.KEYCODE_NUMPAD_ENTER){key("=");return true;}char c=(char)event.getUnicodeChar();String k=String.valueOf(c);if("0123456789.+-%*/=".contains(k)&&c!=0){key(c=='-'?"−":c=='*'?"×":c=='/'?"÷":k);return true;}return super.onKeyDown(code,event);}
}
